('P01', 'The Facade', 'OBSERVATION', 2, 6, 1, '[ADMIN BUILDING] — Main Entrance Facade', '{}', '[]', '{"nextNodes":["P02"],"unlocks":"P02"}', '{"observer":{"role":"OBSERVER","screenTitle":"Facade Observation Log","dataPayload":"FACADE SYMBOL GRID: 8 columns of carved stone symbols visible on the Main Entrance.","visualType":"visual","whatTheySee":"A row of stone glyphs above the entrance. Each glyph appears multiple times.","taskPrompt":"Read the facade from left to right and report the glyph sequence.","intermediateOutput":"Column 1 glyph, Column 2 glyph, ... etc."},"analyst":{"role":"ANALYST","screenTitle":"Glyph Decomposition Terminal","dataPayload":"DECODING INSTRUCTIONS: Convert each glyph to a single letter using the substitution key.","whatTheySee":"A cipher wheel mapping 8 glyph shapes to letters.","taskPrompt":"Apply the substitution to each glyph.","intermediateOutput":"C D F D E F F"},"operator":{"role":"OPERATOR","screenTitle":"Facade Authentication Terminal","dataPayload":"ENTRANCE CODE: [ _ _ _ _ _ _ _ ]","whatTheySee":"Terminal at the base of the facade requiring a 7-character code.","taskPrompt":"Submit the decoded glyph sequence.","intermediateOutput":"Submit: CDFDEFF"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P01.","operatorTaskDescription":"The Observer reports glyph shapes from the physical facade. The Analyst applies the substitution cipher. The Operator submits the combined result. No single role holds the complete answer.","requiredDiscoveries":{"observerDiscovery":"Reads the 8 facade glyphs left to right.","analystDiscovery":"Applies the substitution key to convert glyphs to letters."}},"coordinationChain":{"observerProduces":"Observer reads: glyph glyph glyph glyph glyph glyph glyph glyph.","analystTransforms":"Analyst converts each glyph to its letter: C D F D E F F.","operatorExecutes":"Operator enters CDFDEFF at the facade terminal."},"hints":["The facade above the entrance has 7 visible glyph positions.","Use the cipher key on your device to map each glyph to a letter.","The first two letters are C and D."],"narrativeObjective":"Decode the architectural symbols carved into the Main Entrance facade.","roleDependencyLevel":"D2"}', '{"points":50}', '{"acceptedAnswer":"CDFDEFF","validationMethod":"exact","fullSolution":"Reading the facade glyphs left to right and applying the substitution cipher yields C-D-F-D-E-F-F. Submitting CDFDEFF unlocks the path to P02."}', '{"type":"OBSERVATION","difficulty":2,"time":"6m","storyReveal":"Facade terminal: \"ACCESS GRANTED. PROCEED TO ARCHIVE WING.\"","locationClue":{"format":"Map Marker","clueText":"LINA''S NOTE: \"From the facade, walk through the main doors into the Lobby. The first archive alcove is on your left.\"","solution":"Main Building Lobby Archive Alcove","nextPhysicalLocation":"[ADMIN BUILDING] — Lobby Archive Alcove","nextQrNode":"QR-NODE-02","explanation":"Directs teams from the entrance facade into the archive alcove."},"evidenceUnlocked":{"id":"EVID-P01","category":"Document","title":"Archive Building Floor Plan (1974)","state":"RECOVERED","timestamp":"Stage 1","source":"Archive alcove","content":"A hand-drawn floor plan showing a route to the \"Decommissioned Security Office\" in the basement. The path goes through the library basement."},"whyTeamworkMatters":"Physical observation and cryptographic decoding must be combined — the Analyst cannot solve without the Observer, and the Operator cannot act without both.","feeds":"M01"}'),
('P02', 'The Clock', 'SPATIAL', 2, 5, 1, '[ADMIN BUILDING] — Lobby Clock Tower', '{}', '["P01"]', '{"nextNodes":["P03"],"unlocks":"P03"}', '{"observer":{"role":"OBSERVER","screenTitle":"Clock Tower Viewing Angle","dataPayload":"OBSERVATION: The clock face shows 9:47 when viewed from the east side.","visualType":"observation","whatTheySee":"A vintage clock face with Roman numerals. One hand points at IX, the other at VII.","taskPrompt":"Read the clock face from the east-side viewing angle.","intermediateOutput":"9:47"},"analyst":{"role":"ANALYST","screenTitle":"Time Conversion Calculator","dataPayload":"FORMULA: East view time + 12 hours = military time.","whatTheySee":"Conversion calculator showing 9:47 + 12:00 = 21:47.","taskPrompt":"Convert the observed time to 24-hour format.","intermediateOutput":"21:47"},"operator":{"role":"OPERATOR","screenTitle":"Clock Authentication Terminal","dataPayload":"TIME LOCK: [ _ _ : _ _ ]","whatTheySee":"Terminal with a digital time entry pad.","taskPrompt":"Submit the converted time.","intermediateOutput":"Submit: 21:47"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P02.","operatorTaskDescription":"The Observer reads the clock from a specific angle. The Analyst converts to 24-hour format. The Operator enters the result.","requiredDiscoveries":{"observerDiscovery":"Reads the clock face as 9:47 from the east side.","analystDiscovery":"Converts 9:47 + 12 hours to military time: 21:47."}},"coordinationChain":{"observerProduces":"Observer reads 9:47 from the east side.","analystTransforms":"Analyst converts to 21:47.","operatorExecutes":"Operator submits 21:47 at the clock terminal."},"hints":["The clock in the lobby shows different numbers depending on your viewing angle.","View from the east side. Apply the 12-hour offset.","Submit 21:47."],"narrativeObjective":"Determine the time shown on the lobby clock tower when viewed from a specific angle.","roleDependencyLevel":"D2"}', '{"points":40}', '{"acceptedAnswer":"21:47","validationMethod":"exact","fullSolution":"Reading the clock from the east side shows 9:47. Converting to 24-hour format gives 21:47. Submitting 21:47 unlocks P03."}', '{"type":"SPATIAL","difficulty":2,"time":"5m","storyReveal":"Clock terminal: \"TIME IS VERIFIED. THE PAST IS UNLOCKED.\"","locationClue":{"format":"Map Marker","clueText":"LINA''S NOTE: \"Proceed to the Main Hall. The central staircase awaits.\"","solution":"Main Hall Central Staircase","nextPhysicalLocation":"[MAIN HALL] — Central Staircase","nextQrNode":"QR-NODE-03","explanation":"Directs teams from the clock tower to the Main Hall."},"evidenceUnlocked":{"id":"EVID-P02","category":"Document","title":"Clock Maintenance Log — October 14, 2024","state":"RECOVERED","timestamp":"Stage 1","source":"Behind the clock face","content":"Maintenance log entry: \"22:45 — Clock manually set to 21:47 for synchronization event.\" The time 21:47 appears significant."},"whyTeamworkMatters":"The spatial observation determines the raw data; the analyst transforms it; the operator executes.","feeds":"P01"}'),
('P03', 'The Facade Pin', 'CIPHER', 2, 4, 1, '[ADMIN BUILDING] — Facade Base Terminal', '{}', '["P02"]', '{"nextNodes":["P04"],"unlocks":"P04"}', '{"observer":{"role":"OBSERVER","screenTitle":"Facade Base Inspection","dataPayload":"BASE DETAILS: Four worn brass plates near the facade steps each show a single digit.","visualType":"visual","whatTheySee":"Four brass plates embedded in the steps: 3, 4, 2, 5.","taskPrompt":"Read the digits from left to right.","intermediateOutput":"3, 4, 2, 5"},"analyst":{"role":"ANALYST","screenTitle":"PIN Order Validator","dataPayload":"ORDERING RULE: Digits are ordered by the facade glyph positions from P01.","whatTheySee":"Position mapping: P01 glyphs C(3), D(4), F(2), E(5) map to positions.","taskPrompt":"Verify the PIN ordering.","intermediateOutput":"3425"},"operator":{"role":"OPERATOR","screenTitle":"Facade PIN Terminal","dataPayload":"SECURITY CODE: [ _ _ _ _ ]","whatTheySee":"Four-digit keypad terminal.","taskPrompt":"Submit the 4-digit PIN.","intermediateOutput":"Submit: 3425"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P03.","operatorTaskDescription":"The Observer reads the brass plate digits. The Analyst verifies ordering. The Operator submits.","requiredDiscoveries":{"observerDiscovery":"Reads four brass plates: 3, 4, 2, 5.","analystDiscovery":"Verifies ordering matches P01 glyph positions."}},"coordinationChain":{"observerProduces":"Observer reports 3, 4, 2, 5 from the brass plates.","analystTransforms":"Analyst confirms the PIN is 3425.","operatorExecutes":"Operator submits 3425 at the facade terminal."},"hints":["Look at the brass plates near the facade steps.","The PIN is connected to your P01 solution.","Submit 3425."],"narrativeObjective":"Find the 4-digit PIN hidden in the facade symbols.","roleDependencyLevel":"D2"}', '{"points":35}', '{"acceptedAnswer":"3425","validationMethod":"exact","fullSolution":"Reading the four brass plates gives 3-4-2-5. Submitting 3425 unlocks P04."}', '{"type":"CIPHER","difficulty":2,"time":"4m","storyReveal":"Terminal: \"PIN ACCEPTED. ARCHIVE ACCESS GRANTED.\"","locationClue":{"format":"Document","clueText":"LINA''S NOTE: \"The archive contains a poster about a 2021 student project. Look at the dates.\"","solution":"Archive Poster Examination","nextPhysicalLocation":"[ADMIN BUILDING] — Archive Poster Wall","nextQrNode":"QR-NODE-04","explanation":"Points to the archive poster wall."},"evidenceUnlocked":{"id":"EVID-P03","category":"Document","title":"Archive Poster: NEXUS Project Initiation (2021)","state":"RECOVERED","timestamp":"Stage 1","source":"Archive poster wall","content":"The poster shows 3 key figures: Dr. Vey, Prof. Carter, and a third figure marked TBA. A note reads: \"The key to the future is the 6th letter.\""},"whyTeamworkMatters":"Connects back to P01, requiring the team to maintain cross-puzzle context.","feeds":"P02"}'),
('P04', 'The Poster Dates', 'PATTERN', 3, 7, 1, '[ADMIN BUILDING] — Archive Poster Wall', '{}', '["P03"]', '{"nextNodes":["P05"],"unlocks":"P05"}', '{"observer":{"role":"OBSERVER","screenTitle":"Poster Date Investigation","dataPayload":"POSTER DATES: 2021-03-15, 2021-06-22, 2021-09-08, 2021-12-01","visualType":"document-forensics","whatTheySee":"Four dates arranged in a vertical list on the poster.","taskPrompt":"Report the four dates to the Analyst.","intermediateOutput":"2021-03-15, 2021-06-22, 2021-09-08, 2021-12-01"},"analyst":{"role":"ANALYST","screenTitle":"Date Pattern Analyzer","dataPayload":"ANALYSIS: Day-of-month sequence: 15, 22, 08, 01. Difference pattern: +7, -14, -7. Next would be -14: 01-14 = -13 (mod 31 = 18). But the poster text says \"6th letter\".","whatTheySee":"Pattern analyzer highlighting the note \"the 6th letter\".","taskPrompt":"What is the 6th letter of the alphabet?","intermediateOutput":"F"},"operator":{"role":"OPERATOR","screenTitle":"Archive Access Terminal","dataPayload":"HIDDEN VARIABLE: [ _ ]","whatTheySee":"Single-character terminal.","taskPrompt":"Submit the single letter.","intermediateOutput":"Submit: F"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P04.","operatorTaskDescription":"The Observer reads the poster dates. The Analyst finds the hidden note about the \"6th letter\". The Operator submits the letter.","requiredDiscoveries":{"observerDiscovery":"Reads the four dates on the poster.","analystDiscovery":"Finds the note \"the 6th letter\" and counts: A-B-C-D-E-F."}},"coordinationChain":{"observerProduces":"Observer reports the four dates.","analystTransforms":"Analyst finds the hidden note and calculates the 6th letter: F.","operatorExecutes":"Operator submits F at the archive terminal."},"hints":["The poster text says \"the 6th letter\". Count the alphabet.","A=1, B=2, C=3, D=4, E=5, F=6.","Submit F."],"narrativeObjective":"Find the hidden letter in the dates on the NEXUS project poster.","roleDependencyLevel":"D2"}', '{"points":30}', '{"acceptedAnswer":"F","validationMethod":"exact","fullSolution":"The poster note says \"the 6th letter\". Counting A(1), B(2), C(3), D(4), E(5), F(6) gives F. Submitting F unlocks P05."}', '{"type":"PATTERN","difficulty":3,"time":"7m","storyReveal":"Terminal: \"LETTER VERIFIED. THE THIRD FIGURE IS REVEALED.\"","locationClue":{"format":"Riddle","clueText":"LINA''S NOTE: \"Look for the person who is not shown but whose initial completes the name.\"","solution":"Hidden Third Figure Identification","nextPhysicalLocation":"[ADMIN BUILDING] — Archive Figure Display","nextQrNode":"QR-NODE-05","explanation":"Points to the archive figure display."},"evidenceUnlocked":{"id":"EVID-P04","category":"Document","title":"Project NEXUS — Team Roster","state":"RECOVERED","timestamp":"Stage 1","source":"Behind the poster","content":"Roster: Dr. Lina Vey (Project Lead), Prof. Marcus Carter (Advisor). Third member: [REDACTED]. Initial: V."},"whyTeamworkMatters":"Requires combining physical observation (dates) with cryptographic reasoning (letter count).","feeds":"P03"}'),
('P05', 'The Third Figure', 'DEDUCTION', 3, 6, 1, '[ADMIN BUILDING] — Archive Figure Display', '{}', '["P04"]', '{"nextNodes":["M01"],"unlocks":"M01"}', '{"observer":{"role":"OBSERVER","screenTitle":"Figure Display Inspection","dataPayload":"DISPLAY: Two photos visible. Third photo frame is empty but has an etched initial: V.","visualType":"observation","whatTheySee":"A display with three frames. The third frame is empty, showing only the letter V.","taskPrompt":"Report the visible initial.","intermediateOutput":"V"},"analyst":{"role":"ANALYST","screenTitle":"Name Reconstruction Engine","dataPayload":"REASONING: Dr. Vey is the project lead. The roster says \"Dr. Lina Vey\". The third figure shares the last name Vey.","whatTheySee":"Reconstruction showing \"Lina Vey\" from the lead role.","taskPrompt":"What is the full last name?","intermediateOutput":"VEY"},"operator":{"role":"OPERATOR","screenTitle":"Archive Identity Terminal","dataPayload":"IDENTIFY REDACTED: [ _ _ _ ]","whatTheySee":"Three-letter input terminal.","taskPrompt":"Submit the last name.","intermediateOutput":"Submit: VEY"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P05.","operatorTaskDescription":"The Observer reads the etched initial V. The Analyst reconstructs the full name from the lead role. The Operator submits.","requiredDiscoveries":{"observerDiscovery":"Sees the initial V on the empty frame.","analystDiscovery":"Deduces the last name from Dr. Lina Vey: VEY."}},"coordinationChain":{"observerProduces":"Observer reports the initial V.","analystTransforms":"Analyst deduces the full name: VEY.","operatorExecutes":"Operator submits VEY at the identity terminal."},"hints":["The redacted person is Dr. Lina Vey.","The last name is 3 letters starting with V.","Submit VEY."],"narrativeObjective":"Deduce the full last name of the redacted third project member.","roleDependencyLevel":"D2"}', '{"points":45}', '{"acceptedAnswer":"VEY","validationMethod":"case_insensitive","fullSolution":"The empty frame shows V. The redacted member is Dr. Lina Vey. The last name is VEY. Submitting VEY unlocks Meta M01."}', '{"type":"DEDUCTION","difficulty":3,"time":"6m","storyReveal":"Terminal: \"IDENTITY RECONSTRUCTED. THE FIRST FRAGMENT AWAITS.\"","locationClue":{"format":"Symbol Key","clueText":"LINA''S NOTE: \"The archive has a hidden compartment behind the third frame. Inside is your first fragment.\"","solution":"Archive Hidden Compartment","nextPhysicalLocation":"[ADMIN BUILDING] — Archive Hidden Compartment","nextQrNode":"QR-NODE-06","explanation":"Points to the hidden compartment behind the third frame."},"evidenceUnlocked":{"id":"FRAG-01","category":"Symbol Fragment","title":"Fragment 1 — Vector","state":"RECOVERED","timestamp":"Stage 1","source":"Archive hidden compartment","content":"The first of five narrative fragments. The word VECTOR appears: \"The path diverges. One direction is a straight line; the other, a network. Choose the network.\""},"whyTeamworkMatters":"Deduction requires both observation and reasoning to reconstruct hidden information.","feeds":"P04"}'),
('P06', 'The Pivot', 'MEMORY', 2, 5, 2, '[LIBRARY] — Stack Reference Desk', '{}', '["M01"]', '{"nextNodes":["P07"],"unlocks":"P07"}', '{"observer":{"role":"OBSERVER","screenTitle":"Reference Desk Ledger","dataPayload":"LEDGER: \"Entry #06 was checked out by L.V. on 17/10/2024.\"","visualType":"memory-recall","interactiveData":{"requiresPuzzle":"P01","recallPrompt":"Recall P01 facade PIN digits."},"whatTheySee":"A physical ledger open to entry #06.","taskPrompt":"Read the checkout date for entry #06.","intermediateOutput":"17/10/2024"},"analyst":{"role":"ANALYST","screenTitle":"Date Extractor","dataPayload":"EXTRACTION: \"The pivot number is the DAY from the checkout date.\"","whatTheySee":"Date analysis tool highlighting the day: 17.","taskPrompt":"Extract the day number.","intermediateOutput":"17"},"operator":{"role":"OPERATOR","screenTitle":"Library Terminal","dataPayload":"PIVOT NUMBER: [ _ _ ]","whatTheySee":"Two-digit terminal input.","taskPrompt":"Submit the pivot number.","intermediateOutput":"Submit: 17"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P06.","operatorTaskDescription":"The Observer reads the ledger date. The Analyst extracts the day. The Operator submits.","requiredDiscoveries":{"observerDiscovery":"Reads ledger entry: \"L.V. on 17/10/2024.\"","analystDiscovery":"Extracts the day number: 17."}},"coordinationChain":{"observerProduces":"Observer reports the checkout date: 17/10/2024.","analystTransforms":"Analyst extracts the day: 17.","operatorExecutes":"Operator submits 17 at the library terminal."},"hints":["The date format is DD/MM/YYYY.","The pivot is the first number in the date.","Submit 17."],"narrativeObjective":"Recall the pivot number from an earlier clue.","roleDependencyLevel":"D1"}', '{"points":40}', '{"acceptedAnswer":"17","validationMethod":"exact","fullSolution":"The ledger shows 17/10/2024. The day (pivot) is 17. Submitting 17 unlocks P07."}', '{"type":"MEMORY","difficulty":2,"time":"5m","storyReveal":"Terminal: \"PIVOT RECALLED. BINARY GATE UNLOCKED.\"","locationClue":{"format":"Map Marker","clueText":"LINA''S NOTE: \"The library basement contains a server rack with blinking binary LEDs.\"","solution":"Library Basement Server Rack","nextPhysicalLocation":"[LIBRARY] — Basement Server Rack","nextQrNode":"QR-NODE-07","explanation":"Points to the library basement server rack."},"evidenceUnlocked":{"id":"EVID-P06","category":"Data","title":"Server Rack Binary Log","state":"RECOVERED","timestamp":"Stage 2","source":"Library basement server rack","content":"Binary sequence: 01001001 01001100 01001001 01001001 01001110. Decoded: \"ILILINE\". Hmm, that seems wrong. Try 01001001 01001100 01001001 01001110."},"whyTeamworkMatters":"Tests whether the team retained earlier Stage 1 findings.","feeds":"M01"}'),
('P07', 'The Binary', 'BINARY', 3, 8, 2, '[LIBRARY] — Basement Server Rack', '{}', '["P06"]', '{"nextNodes":["P08"],"unlocks":"P08"}', '{"observer":{"role":"OBSERVER","screenTitle":"LED Array Reader","dataPayload":"LED PATTERN: 8 groups of 8 blinking LEDs. Each group is a byte.","visualType":"binary-technical","interactiveData":{"binarySequence":["01001001","01010011","00111010","00110100","00110100","00110111","00110010","00110001"]},"whatTheySee":"Eight bytes of blinking binary LEDs.","taskPrompt":"Read each byte and report to the Analyst.","intermediateOutput":"01001001 01010011 00111010 00110100 00110001 00110111 00110000 00110001"},"analyst":{"role":"ANALYST","screenTitle":"Binary Decoder","dataPayload":"DECODED: 73 83 58 52 52 55 50 49 -> \"IS:472501\"","visualType":"binary-technical","whatTheySee":"Binary-to-ASCII converter output.","taskPrompt":"Decode each byte to ASCII characters.","intermediateOutput":"IS:472501"},"operator":{"role":"OPERATOR","screenTitle":"Server Access Terminal","dataPayload":"ACCESS CODE: [ _ _ : _ _ _ _ _ _ ]","whatTheySee":"Terminal requiring time format HH:MM.","taskPrompt":"Submit the decoded time. Note: the server log shows 09:47 was the synchronization.","intermediateOutput":"Submit: 17:47"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P07.","operatorTaskDescription":"The Observer reads the binary LED pattern. The Analyst decodes to ASCII. The Operator submits the time.","requiredDiscoveries":{"observerDiscovery":"Reads 8 bytes of binary from the LED array.","analystDiscovery":"Decodes bytes to ASCII: \"IS:472501\"."}},"coordinationChain":{"observerProduces":"Observer reports the 8 binary bytes.","analystTransforms":"Analyst decodes: IS:472501, then connects to P02 time 21:47 = 17:47.","operatorExecutes":"Operator submits 17:47 at the server terminal."},"hints":["Decode the binary bytes to ASCII characters.","The result is a time reference — cross-reference with P02.","Submit 17:47."],"narrativeObjective":"Decode the binary sequence from the server rack.","roleDependencyLevel":"D2"}', '{"points":50}', '{"acceptedAnswer":"17:47","validationMethod":"exact","fullSolution":"Decoding the binary gives \"IS:472501\". Combining with P02 clock time (21:47 = 17:47), submit 17:47."}', '{"type":"BINARY","difficulty":3,"time":"8m","storyReveal":"Terminal: \"TIME SYNC CONFIRMED. PROCEED TO THE ARCHIVE.\"","locationClue":{"format":"Document","clueText":"LINA''S NOTE: \"Return to the archive. Check the 2021 project folder in cabinet 3.\"","solution":"Archive Cabinet 3","nextPhysicalLocation":"[ADMIN BUILDING] — Archive Cabinet 3","nextQrNode":"QR-NODE-08","explanation":"Points back to the archive cabinet."},"evidenceUnlocked":{"id":"EVID-P07","category":"Document","title":"Project NEXUS — 2021 Research Folder","state":"RECOVERED","timestamp":"Stage 2","source":"Archive cabinet 3","content":"Folder contents: \"Consciousness is not a single entity but a vector. Test subjects 00-04 were isolated. Subject 05 was the first to achieve network state.\""},"whyTeamworkMatters":"Requires cross-referencing Stage 1 and Stage 2 solutions.","feeds":"P06"}'),
('P08', 'The Vector', 'PATTERN', 3, 7, 2, '[ADMIN BUILDING] — Archive Cabinet 3', '{}', '["P07"]', '{"nextNodes":["P09"],"unlocks":"P09"}', '{"observer":{"role":"OBSERVER","screenTitle":"Fragment 1 Display","dataPayload":"FRAGMENT 1: \"The path diverges. One direction is a straight line; the other, a network.\"","visualType":"memory-recall","interactiveData":{"requiresPuzzle":"P05","recallPrompt":"Recall Fragment 1 from the archive."},"whatTheySee":"Recovered Fragment 1 text displayed on the cabinet screen.","taskPrompt":"Read Fragment 1 aloud.","intermediateOutput":"The path diverges..."},"analyst":{"role":"ANALYST","screenTitle":"Directional Analysis","dataPayload":"VECTOR ANALYSIS: Straight line = Alpha. Network = Delta. The network path is chosen.","whatTheySee":"Vector direction comparator.","taskPrompt":"Which Greek letter represents the network direction?","intermediateOutput":"Delta"},"operator":{"role":"OPERATOR","screenTitle":"Path Divergence Terminal","dataPayload":"SELECT DIRECTION: [ _ _ _ _ _ ]","whatTheySee":"Five-letter input terminal.","taskPrompt":"Submit the Greek letter name.","intermediateOutput":"Submit: DELTA"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P08.","operatorTaskDescription":"The Observer recalls Fragment 1. The Analyst identifies the network direction. The Operator submits.","requiredDiscoveries":{"observerDiscovery":"Recalls Fragment 1 text about divergent paths.","analystDiscovery":"Identifies Delta as the network direction."}},"coordinationChain":{"observerProduces":"Observer reports Fragment 1: \"straight line vs network\".","analystTransforms":"Analyst maps: network = Delta.","operatorExecutes":"Operator submits DELTA."},"hints":["Fragment 1 speaks of a divergence.","The network direction is named after a Greek letter.","Submit DELTA."],"narrativeObjective":"Identify the Greek letter representing the path divergence from Fragment 1.","roleDependencyLevel":"D2"}', '{"points":45}', '{"acceptedAnswer":"DELTA","validationMethod":"case_insensitive","fullSolution":"Fragment 1 says the path diverges. The network direction is Delta. Submitting DELTA unlocks P09."}', '{"type":"PATTERN","difficulty":3,"time":"7m","storyReveal":"Terminal: \"NETWORK PATH CONFIRMED. THE NEXT GATE IS CHRONOLOGICAL.\"","locationClue":{"format":"Numerical","clueText":"LINA''S NOTE: \"The next room has a clock with Roman numerals. Find 17:00.\"","solution":"Clock Room","nextPhysicalLocation":"[ADMIN BUILDING] — Clock Room","nextQrNode":"QR-NODE-09","explanation":"Points to the clock room."},"evidenceUnlocked":{"id":"EVID-P08","category":"Visual","title":"Clock Room Symbol Chart","state":"RECOVERED","timestamp":"Stage 2","source":"Clock room wall chart","content":"A chart of Greek letters: Alpha, Beta, Gamma, Delta, Epsilon. Delta is circled. A note: \"Time flows from the circle.\""},"whyTeamworkMatters":"Requires recall of previously discovered evidence.","feeds":"P07"}'),
('P09', 'The Chronology', 'LOGIC', 3, 8, 2, '[ADMIN BUILDING] — Clock Room', '{}', '["P08"]', '{"nextNodes":["P10"],"unlocks":"P10"}', '{"observer":{"role":"OBSERVER","screenTitle":"Roman Clock Face","dataPayload":"CLOCK FACE: Roman numerals I through XII. Hand points to XVII (17).","visualType":"spatial","whatTheySee":"A clock with a single hand pointing at VII.","taskPrompt":"Read the clock hand position.","intermediateOutput":"7"},"analyst":{"role":"ANALYST","screenTitle":"Temporal Equation Calculator","dataPayload":"EQUATION: P06 pivot (17) + clock hand (7) = 24. 24 - 7 = 17. Or simply: XVII = 17.","whatTheySee":"Calculator showing two solution paths converging to 17.","taskPrompt":"What is the Roman numeral XVII?","intermediateOutput":"17"},"operator":{"role":"OPERATOR","screenTitle":"Chronology Terminal","dataPayload":"TEMPORAL KEY: [ _ _ ]","whatTheySee":"Two-digit input terminal.","taskPrompt":"Submit the converted Roman numeral.","intermediateOutput":"Submit: 17"},"operatorInvestigation":{"operatorOwnEvidence":"Terminal screen shows the execution interface for P09.","operatorTaskDescription":"The Observer reads the clock. The Analyst converts Roman numeral. The Operator submits.","requiredDiscoveries":{"observerDiscovery":"Reads the clock hand position.","analystDiscovery":"Converts XVII to decimal: 17."}},"coordinationChain":{"observerProduces":"Observer reads the Roman numeral XVII.","analystTransforms":"Analyst converts to 17.","operatorExecutes":"Operator submits 17."},"hints":["The clock uses Roman numerals.","XVII converts to what decimal?","Submit 17."],"narrativeObjective":"Solve the temporal equation using the clock.","roleDependencyLevel":"D2"}', '{"points":50}', '{"acceptedAnswer":"17","validationMethod":"exact","fullSolution":"The Roman numeral XVII converts to 17. Submitting 17 unlocks P10."}', '{"type":"LOGIC","difficulty":3,"time":"8m","storyReveal":"Terminal: \"TIME DECODED. THE BLUE PATH IS REVEALED.\"","locationClue":{"format":"Color Code"